}

/// A decision put to the person.
struct PersonCall: Codable, Hashable {
    let id: String
    let project: String
    let kind: CallKind
    /// Who asks.
    let asker: CallAsker
    /// Other agents waiting on the same thing, which this one answer covers.
    let joined: [CallAsker]?
    /// What the person asked for, in their words: the card's heading.
    let askedFor: String?
    /// The decision, in one line.
    let question: String
    let context: String?
    /// What the asker goes on with until the person answers, in its own words, one line; none
    /// when it waits. Never on a production call.
    let assumption: String?
    let options: [CallOption]
    /// The option the asker would take, by its id.
    let pick: String?
    /// The strongest point against the pick.
    let against: String?
    let evidence: [CallEvidence]?
    /// Exactly what runs on a yes, shown only once the card is opened.
    let action: String?
    /// A weighty call comes as a short brief.
    let brief: CallBrief?
    /// The production place it changes.
    let place: CallPlace?
    /// Not mine hands it back: never on a production call.
    let canHandBack: Bool
    /// More than one option may be picked.
    let multi: Bool?
    /// The answer is a secret, typed into a hidden field and never shown again.
    let secret: Bool?
    let raisedAt: Int
    let state: CallState
    let answer: CallAnswer?
    let outcome: CallOutcome?
}

/// What makes a decision the person's own.
enum CallKind: String, Codable, Hashable {
    /// A change to a production place. It passes only by its button, on a client that drew it,
    /// and is never handed back.
    case production
    /// Spending money.
    case money
    /// Taste or product direction.
    case taste
    /// Access only the person has, such as a sign-in or a password.
    case access
    /// One added after this build.
    case unknown

    init(from decoder: Decoder) throws {
        self = Self(rawValue: try decoder.singleValueContainer().decode(String.self)) ?? .unknown
    }
}

/// An agent that waits on a call.
struct CallAsker: Codable, Hashable {
    let agentId: String
    /// Its name, such as Wren.
    let name: String
    let cli: String
    /// The asker is its project's chief.
    let chief: Bool?
}

/// One of the answers the person picks among.
struct CallOption: Codable, Hashable {
    let id: String
    let label: String
    let detail: String?
    /// A screenshot or mockup of it, in the core's own folder. A taste call has one per option.
    let picture: String?
}

/// Something worth looking at before answering, such as checks that passed or the page as it
/// will look.
struct CallEvidence: Codable, Hashable {
    let what: String
    let picture: String?
}

/// What a weighty call, such as a cutover or a public release, says before its options.
struct CallBrief: Codable, Hashable {
    let tried: String
    /// What the evidence shows.
    let shows: String
    /// What can't be undone once it goes.
    let cannotUndo: String
}

/// A place a call changes, by an id that outlives a rename.
struct CallPlace: Codable, Hashable {
    let id: String
    let name: String
}

enum CallState: String, Codable, Hashable {
    case open
    case answered
    /// Nobody answers it any more: the asker went on another way or closed.
    case closed
    /// One added after this build.
    case unknown

    init(from decoder: Decoder) throws {
        self = Self(rawValue: try decoder.singleValueContainer().decode(String.self)) ?? .unknown
    }
}

struct CallAnswer: Codable, Hashable {
    /// The option picked, by its id.
    let option: String?
    /// The options picked on a call that takes several.
    let options: [String]?
    /// What the person added to the option they picked.
    let note: String?
    /// The person's answer in their own words, with no option picked.
    let words: String?
    let at: Int
    /// How long the call waited on the person.
    let waitedMs: Int
}

/// What came of a call, such as "Shipped · healthy".
struct CallOutcome: Codable, Hashable {
    let result: CallResult
    /// What the place's health check said after it shipped.
    let healthy: Bool?
    /// The place can take it back.
    let rollBack: Bool?
    /// Why it came to that, where the result alone does not say.
    let why: CallWhy?
    let at: Int
}

enum CallResult: String, Codable, Hashable {
    /// The asker was told the answer.
    case heard
    case shipped
    /// The person said no, so it did not ship.
    case notShipped
    /// It went, and failed.
    case failed
    /// It started, and Sikemux restarted before it was seen to end, so it may have run.
    case mayHaveRun
    /// Handed back to the asker's lead, or to the asker, to decide.
    case handedBack
    /// Closed with no answer from the person.
    case withdrawn
    /// One added after this build.
    case unknown

    init(from decoder: Decoder) throws {
        self = Self(rawValue: try decoder.singleValueContainer().decode(String.self)) ?? .unknown
    }
}

enum CallWhy: String, Codable, Hashable {
    /// Sikemux restarted after the person said yes and before it ran, so the yes lapsed.
    case restarted
    /// One added after this build.
    case unknown

    init(from decoder: Decoder) throws {
        self = Self(rawValue: try decoder.singleValueContainer().decode(String.self)) ?? .unknown
    }
}

/// How agents' faces look, as the person picked.
struct FaceStyle: Codable, Hashable {
    /// Faces move with what their agents are doing.
    let motion: Bool
}

/// How busy a host is, for the rows clients show it in.
struct HostLoad: Codable, Hashable {
    /// More threads want to run than its cores take, so agents' simulators and builds wait.
    let overloaded: Bool?
    /// The one-minute load average, rounded, while it is overloaded.
    let loadAverage: Int?
    let cores: Int
    /// The builds agents run or wait to run, oldest first, while it is overloaded.
    let builds: [AgentBuild]?
}

/// A heavy command an agent started, such as `cargo build` or `pnpm test`, running or waiting its turn.
struct AgentBuild: Codable, Hashable {
    let agentId: String?
    let command: String
}

/// What a call that takes nothing is sent; whatever a client sends reads as nothing.
struct NoParams: Codable, Hashable {}

/// How the person wants Sikemux to behave, the same in every app. A field
/// left out reads as its default.
struct Preferences: Codable, Hashable {
    /// How the island over the MacBook notch behaves.
    let notch: NotchSettings
}

struct CatalogAgent: Codable, Hashable {
    /// Its id, such as `claude`.
    let type: String
    let label: String
}

struct AgentQuestion: Codable, Hashable {
    let id: String
    /// What the person is asked, which a lead that passed it on may have
    /// reworded.
    let text: String
    let choices: [QuestionChoice]
    /// Why it reached the person rather than the lead it went to first, such
    /// as "@Maple raised this".
    let viaNote: String?
}

struct QuestionChoice: Codable, Hashable {
    let label: String
}

struct AnswerParams: Codable, Hashable {
    let id: String
    var answer: String?
    /// Files attached to `answer`, by where the host keeps them.
    var paths: [String]?
    /// What was sent with `answer`.
    var context: [ChatContext]?
    var choice: Int?
    /// The choices picked on a question that takes several.
    var choices: [Int]?
    /// The assumption the agent went on is right.
    var fine: Bool = false
}

/// What answers a call: an option, with a note, or the person's own words, with any files.
struct AnswerCallParams: Codable, Hashable {
    let id: String
    var option: String?
    /// The options picked on a call that takes several.
    var options: [String]?
    var note: String?
    var words: String?
    /// Lets the assumption the asker goes on with stand, on a call that offers no options.
    var fine: Bool?
    /// Files attached to the note or the words, by where the host keeps them.
    var paths: [String]?
}

struct CallParams: Codable, Hashable {
    let id: String
}
